// Junta os trechos de todas as consultas num item só.
//
// Mesmo papel do nó de mesmo nome no fluxo sem reescrita (fan-out, campos que
// o vector store derruba, pageContent vazio, corte de relevância), com duas
// diferenças:
//
// 1. MAIS DE UMA BUSCA. Cada consulta da reescrita fez a sua. A FAQ que veio
//    em duas conta uma vez só, com o melhor score.
//
// 2. RODÍZIO, E NÃO SÓ SCORE. O melhor trecho de cada consulta entra primeiro,
//    depois o segundo de cada uma, e assim até 10. Ordenando só por score, a
//    consulta específica (a receita de cada remédio, 0,90) empurraria para fora
//    a consulta geral (a FAQ de receita vencida, 0,88), que é justamente a que
//    a reescrita existe para trazer.
//
// O corte continua 0.82, o mesmo dos outros fluxos.
const dados = $('Consultas').first().json;
const LIMIAR_SCORE = 0.82;
const MAXIMO_TRECHOS = 10;
const TOP_K = 10;

const entradas = $input.all();
const pulouBusca = entradas.length === 1 && entradas[0].json && entradas[0].json.PularBusca === true;

const porConsulta = new Map();
const debug = [];

if (!pulouBusca) {
  entradas.forEach((item, posicao) => {
    // De qual consulta veio o trecho: o n8n liga cada saída à entrada que a
    // gerou. Sem essa ligação, a ordem é consulta a consulta, TOP_K de cada.
    const ligado = item.pairedItem && typeof item.pairedItem.item === 'number' ? item.pairedItem.item : null;
    const indice = ligado !== null ? ligado : Math.floor(posicao / TOP_K);

    const doc = (item.json && item.json.document) || item.json || {};
    const meta = doc.metadata || {};
    const score = item.json && typeof item.json.score === 'number' ? item.json.score : 1;
    const passou = score >= LIMIAR_SCORE;

    // `||` e não `??`: string vazia precisa cair para a próxima fonte.
    let texto = (doc.pageContent || '').trim();
    if (!texto) texto = (meta.text || '').trim();
    if (!texto && (meta.question || meta.answer)) {
      texto = [
        meta.category ? 'Assunto: ' + meta.category : null,
        meta.question ? 'Pergunta: ' + meta.question : null,
        meta.answer ? 'Resposta: ' + meta.answer : null,
      ].filter(Boolean).join('\n');
    }

    const faqId = meta._id || meta.id || doc.id || (item.json && item.json.id) || null;
    debug.push({
      score: Number(score.toFixed(4)),
      usado: false,
      faqId: faqId ? String(faqId) : null,
      category: meta.category || null,
      question: meta.question || null,
      previa: texto ? texto.slice(0, 240) : null,
      consulta: dados.Consultas[indice] || null,
    });

    if (passou && texto) {
      const chave = faqId ? String(faqId) : (meta.question || '') + '|' + (meta.category || '') + '|' + texto.slice(0, 80);
      if (!porConsulta.has(indice)) porConsulta.set(indice, []);
      porConsulta.get(indice).push({ chave, texto, score, posicao: debug.length - 1 });
    }
  });
}

const listas = [...porConsulta.keys()]
  .sort((a, b) => a - b)
  .map((indice) => porConsulta.get(indice).sort((a, b) => b.score - a.score));
const escolhidos = [];
const vistos = new Set();
for (let rodada = 0; escolhidos.length < MAXIMO_TRECHOS && listas.some((l) => l.length > rodada); rodada++) {
  for (const lista of listas) {
    const trecho = lista[rodada];
    if (!trecho || vistos.has(trecho.chave) || escolhidos.length >= MAXIMO_TRECHOS) continue;
    vistos.add(trecho.chave);
    escolhidos.push(trecho);
    debug[trecho.posicao].usado = true;
  }
}

const contexto = escolhidos.map((t, i) => '[Trecho ' + (i + 1) + ']\n' + t.texto).join('\n\n');

return [
  {
    json: {
      ...dados,
      ContextoFaq: contexto,
      TemContexto: escolhidos.length > 0,
      QtdTrechos: escolhidos.length,
      TrechosDebug: debug,
      LimiarScore: LIMIAR_SCORE,
    },
  },
];

