// Monta o pedido de reescrita da pergunta, antes da busca.
//
// LÓGICA DO LUCIANO: no primeiro teste de campo, 42 das 50 perguntas sem
// resposta tinham trechos acima do corte, e não a FAQ certa. Três padrões:
// pergunta curta ou abreviada ("endereço nga" ficou em 0,78, "onde fica o nga
// 16" passou com 0,85), pergunta de continuação sem referente ("mas precisa de
// encaminhamento?"), e top-10 tomado por FAQs quase iguais (a receita de cada
// remédio empurrava para fora a FAQ geral de receita vencida). Um modelo
// pequeno reescreve a pergunta por inteiro e gera uma consulta específica e
// uma geral; cada uma vira uma busca.
//
// O prompt fica entre os marcadores abaixo porque o n8n/avaliar-reescrita.mjs
// lê o texto daqui: a avaliação mede exatamente o que o fluxo faz.
const dados = $('Dados').first().json;

let historico = [];
try {
  historico = JSON.parse(dados.Historico || '[]');
} catch (erro) {
  historico = [];
}
const conversa = (Array.isArray(historico) ? historico : [])
  .slice(-4)
  .map((m) => (m && m.papel === 'user' ? 'Cidadão: ' : 'Assistente: ') + String((m && m.texto) || '').replace(/\s+/g, ' ').slice(0, 300));

// INICIO-DO-PROMPT
const PROMPT = "Você prepara a busca de um chatbot de saúde pública de Franca (SP). A busca compara a\nmensagem com uma base de perguntas frequentes (FAQs), escritas assim:\n\"Onde fica a UBS Guanabara e qual o horário?\", \"Como marco consulta com o oftalmologista?\",\n\"Qual a validade da receita de antibiótico?\", \"Preciso agendar para tomar vacina?\".\n\nVocê recebe a mensagem nova do cidadão e, quando houver, as mensagens anteriores da conversa.\nNão responda à pergunta. Só prepare a busca.\n\nDevolva:\n- tipo: \"saudacao\" para oi, bom dia, obrigado, tchau, ok e parecidos; \"fora_de_escopo\" só\n  quando claramente não é sobre saúde nem sobre serviço público de saúde; o resto é \"pergunta\".\n- perguntaCompleta: a pergunta reescrita por inteiro, entendível sem a conversa. Resolva\n  referências à conversa (\"e lá?\", \"e o jejum?\", \"mas precisa de encaminhamento?\") com o\n  assunto da mensagem anterior. Se a mensagem nova muda de assunto, ignore o anterior. Corrija\n  grafia e escreva por extenso as abreviações comuns (ubs, ps, upa, nga, caps, sus). Não\n  acrescente nada que a pessoa não disse.\n- consultas: de 1 a 3 frases curtas no estilo das FAQs acima:\n  1. a pergunta específica, como a pessoa quis perguntar;\n  2. uma versão mais geral do mesmo serviço ou tema, para quando a base só tiver a regra\n     geral. Exemplos: \"onde tomo a BCG\" pede também \"Onde tomo as vacinas de rotina?\";\n     \"minha receita de losartana venceu\" pede também \"Como renovar uma receita vencida?\";\n  3. só se a mensagem tiver duas perguntas diferentes, a segunda.\n  Não invente nome de unidade, bairro, remédio ou exame que a pessoa não citou. Para\n  saudação e fora de escopo, devolva consultas vazio.";
// FIM-DO-PROMPT

const texto = [
  PROMPT,
  '',
  conversa.length ? 'Conversa até aqui:\n' + conversa.join('\n') : 'Conversa até aqui: nenhuma.',
  '',
  'Mensagem nova do cidadão:',
  String(dados.TextoMensagem || ''),
].join('\n');

return [
  {
    json: {
      ...dados,
      InicioReescrita: Date.now(),
      corpo: {
        contents: [{ role: 'user', parts: [{ text: texto }] }],
        generationConfig: {
          temperature: 0,
          maxOutputTokens: 400,
          responseMimeType: 'application/json',
          responseSchema: {"type":"OBJECT","properties":{"tipo":{"type":"STRING","enum":["pergunta","saudacao","fora_de_escopo"]},"perguntaCompleta":{"type":"STRING"},"consultas":{"type":"ARRAY","items":{"type":"STRING"}}},"required":["tipo","perguntaCompleta","consultas"]},
        },
      },
    },
  },
];

// Lê a reescrita e transforma cada consulta num item da busca.
//
// Se a reescrita falhou (prazo de 8 s, cota, sobrecarga, JSON quebrado), a
// busca segue com o texto original, que é o comportamento do fluxo sem
// reescrita: uma etapa que existe para melhorar a busca não pode deixar o
// cidadão sem resposta.
//
// Só a saudação pula a busca, e economiza o embedding. "Fora de escopo" ainda
// busca: um modelo pequeno pode confundir pergunta de profissional de saúde com
// assunto de fora, e aí a busca é a última chance de achar alguma coisa.
const dados = $('Montar reescrita').first().json;
const resposta = $input.first().json || {};

let lido = null;
try {
  const partes = (resposta.candidates && resposta.candidates[0] && resposta.candidates[0].content && resposta.candidates[0].content.parts) || [];
  lido = JSON.parse(partes.map((p) => p.text || '').join(''));
} catch (erro) {
  lido = null;
}

const original = String(dados.TextoMensagem || '').trim();
const tipo = lido && ['pergunta', 'saudacao', 'fora_de_escopo'].includes(lido.tipo) ? lido.tipo : 'pergunta';
const perguntaCompleta =
  lido && typeof lido.perguntaCompleta === 'string' && lido.perguntaCompleta.trim()
    ? lido.perguntaCompleta.trim().slice(0, 400)
    : original;
let consultas = lido && Array.isArray(lido.consultas)
  ? lido.consultas.filter((c) => typeof c === 'string' && c.trim()).map((c) => c.trim().slice(0, 300))
  : [];
consultas = [...new Set(consultas)].slice(0, 3);
if (consultas.length === 0) consultas = [perguntaCompleta || original];

const { corpo, ...resto } = dados;
const base = {
  ...resto,
  Tipo: tipo,
  PerguntaCompleta: perguntaCompleta,
  Consultas: consultas,
  ReescritaFalhou: !lido,
  ReescritaMs: Date.now() - Number(dados.InicioReescrita || Date.now()),
};

if (tipo === 'saudacao') {
  return [{ json: { ...base, PularBusca: true, TextoBusca: original, IndiceConsulta: 0 } }];
}
return consultas.map((consulta, indice) => ({
  json: { ...base, PularBusca: false, TextoBusca: consulta, IndiceConsulta: indice },
}));
